import{_ as a,a as o,b as e}from"./chunks/payload-3.Dh4aD50w.js";import{_ as r,o as l,c as i,a5 as n}from"./chunks/framework.CcrBcQWS.js";const m=JSON.parse('{"title":"Payload Configuration","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/payload_setting.md","filePath":"manual/troubleshooting/payload_setting.md","lastUpdated":1787021357000}'),s={name:"manual/troubleshooting/payload_setting.md"};function d(u,t,p,c,g,f){return l(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="payload-configuration" tabindex="-1">Payload Configuration <a class="header-anchor" href="#payload-configuration" aria-label="Permalink to &quot;Payload Configuration&quot;">​</a></h1><p>In RBQGUI, use <strong>Payload Configuration</strong> to enter the mass and offsets of attached payloads and improve walking stability.</p><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h2><ul><li>Place the robot on a flat, safe surface.</li><li>Make sure RBQGUI is connected to the robot.</li><li>Check the payload center position in advance (X/Y/Z offsets).</li></ul><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li>Open <strong>Payload Configuration</strong> in RBQGUI.</li><li>Enter the following values in the top input fields: <ul><li><strong>Mass (kg)</strong>: Mass of the attached payload</li><li><strong>Offset X/Y/Z (m)</strong>: Payload center position in the robot coordinate frame</li></ul></li></ol><figure><img src="'+a+'" alt="Payload Configuration input screen"></figure><ol start="3"><li>Click <strong>+ Add</strong> to add the values to the <strong>Added Payload</strong> list.</li><li>Confirm the values were added correctly, then click <strong>Set Payload</strong>.</li></ol><figure><img src="'+o+'" alt="Added Payload list with entered values"></figure><ol start="5"><li>When the confirmation popup appears, verify the values (mass and offsets) and click <strong>Confirm</strong> to apply them to the robot.</li></ol><figure><img src="'+e+'" alt="Payload application confirmation dialog"></figure><ol start="6"><li>After applying, use <strong>Load Payload</strong> if needed to reload and verify the currently applied value.</li></ol><h2 id="button-functions" tabindex="-1">Button Functions <a class="header-anchor" href="#button-functions" aria-label="Permalink to &quot;Button Functions&quot;">​</a></h2><ul><li><strong>+ Add</strong>: Add entered mass/offset values to the candidate list</li><li><strong>Clear</strong>: Clear current input fields</li><li><strong>Set Payload</strong>: Apply the Added Payload value to the robot</li><li><strong>Load Payload</strong>: Load the payload value currently applied on the robot</li><li><strong>Reset Payload</strong>: Reset payload values to default state</li></ul>',14)])])}const _=r(s,[["render",d]]);export{m as __pageData,_ as default};
